CREATE TABLE IF NOT EXISTS campaign_writer_attestation_v1 (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,owner TEXT NOT NULL,principal_id TEXT NOT NULL UNIQUE,
  credential_mac TEXT NOT NULL,expires_at INTEGER NOT NULL,attested_at INTEGER NOT NULL,master_proof_mac TEXT);

CREATE TABLE IF NOT EXISTS crm_writer_bridge_config_v1(singleton INTEGER PRIMARY KEY CHECK(singleton=1),issuer TEXT NOT NULL,namespace TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS crm_writer_bridge_life_v1(lifecycle_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,owner TEXT NOT NULL,version INTEGER NOT NULL,active_generation INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL CHECK(state IN ('active','revoking','revoked')),revoke_operation_id TEXT NOT NULL UNIQUE);
 CREATE TABLE IF NOT EXISTS crm_writer_bridge_op_v1(operation_id TEXT PRIMARY KEY,commit_operation_id TEXT NOT NULL UNIQUE,lifecycle_id TEXT NOT NULL REFERENCES crm_writer_bridge_life_v1,kind TEXT NOT NULL CHECK(kind IN ('issue','renew','revoke')),phase TEXT NOT NULL CHECK(phase IN ('queued','prepare_uncertain','prepared','commit_uncertain','committed','attested','promoted','expired','revoke_pending','revoked')),request_json TEXT NOT NULL,request_mac TEXT NOT NULL,ciphertext TEXT,cipher_mac TEXT,bearer_mac TEXT,prepared_json TEXT,prepared_mac TEXT,committed_json TEXT,committed_mac TEXT);
 CREATE UNIQUE INDEX IF NOT EXISTS crm_writer_bridge_open_v1 ON crm_writer_bridge_op_v1(lifecycle_id) WHERE kind<>'revoke' AND phase NOT IN ('promoted','expired','revoked');

CREATE TABLE IF NOT EXISTS crm_writer_auth_config_v1(singleton INTEGER PRIMARY KEY CHECK(singleton=1),issuer_id TEXT NOT NULL,namespace_id TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS crm_writer_auth_admission_v1(user_id TEXT PRIMARY KEY REFERENCES users(id),lifecycle_id TEXT NOT NULL UNIQUE,version INTEGER NOT NULL CHECK(version>0),owner TEXT NOT NULL,issuer_id TEXT NOT NULL,namespace_id TEXT NOT NULL,approved INTEGER NOT NULL CHECK(approved IN(0,1)));
 CREATE TABLE IF NOT EXISTS crm_writer_auth_binding_v1(user_id TEXT PRIMARY KEY REFERENCES users(id),lifecycle_id TEXT NOT NULL,version INTEGER NOT NULL,owner TEXT NOT NULL,issuer_id TEXT NOT NULL,namespace_id TEXT NOT NULL,principal_id TEXT NOT NULL UNIQUE,generation INTEGER NOT NULL CHECK(generation>0),expires_at INTEGER NOT NULL,credential_mac TEXT NOT NULL);
